import{_ as a,o as s,c as t,a2 as e}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"Ограничение частоты запросов","description":"","frontmatter":{},"headers":[],"relativePath":"ru/advanced/ratelimit.md","filePath":"ru/advanced/ratelimit.md","lastUpdated":1784903584000}'),n={name:"ru/advanced/ratelimit.md"};function l(o,i,r,h,d,p){return s(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="ограничение-частоты-запросов" tabindex="-1">Ограничение частоты запросов <a class="header-anchor" href="#ограничение-частоты-запросов" aria-label="Permalink to &quot;Ограничение частоты запросов&quot;">​</a></h1><h2 id="обзор" tabindex="-1">Обзор <a class="header-anchor" href="#обзор" aria-label="Permalink to &quot;Обзор&quot;">​</a></h2><p>swag2mcp имеет встроенный ограничитель частоты, который предотвращает слишком частые вызовы одного и того же эндпоинта API со стороны LLM. Это защищает от случайных дублирующих вызовов и соблюдает лимиты частоты API.</p><h2 id="как-это-работает" tabindex="-1">Как это работает <a class="header-anchor" href="#как-это-работает" aria-label="Permalink to &quot;Как это работает&quot;">​</a></h2><p>Каждый эндпоинт имеет период охлаждения. Если LLM пытается вызвать тот же эндпоинт снова в течение периода охлаждения, вызов отклоняется со структурированной ошибкой.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>t=0s  → invoke(endpoint) → выполняется</span></span>
<span class="line"><span>t=2s  → invoke(endpoint) → отклонён с ошибкой rate_limit</span></span>
<span class="line"><span>t=12s → invoke(endpoint) → выполняется (период охлаждения прошёл)</span></span></code></pre></div><h3 id="поведение-по-умолчанию" tabindex="-1">Поведение по умолчанию <a class="header-anchor" href="#поведение-по-умолчанию" aria-label="Permalink to &quot;Поведение по умолчанию&quot;">​</a></h3><ul><li><strong>Период охлаждения:</strong> 10 секунд на эндпоинт</li><li><strong>Область действия:</strong> На эндпоинт — вызов эндпоинта A не влияет на эндпоинт B</li><li><strong>Ответ об ошибке:</strong> LLM получает <code>LLMError</code> с кодом <code>rate_limit</code> и сообщением, указывающим, сколько ждать</li><li><strong>Сброс:</strong> После 10 секунд бездействия на этом эндпоинте</li></ul><h3 id="формат-ошибки" tabindex="-1">Формат ошибки <a class="header-anchor" href="#формат-ошибки" aria-label="Permalink to &quot;Формат ошибки&quot;">​</a></h3><p>При превышении лимита частоты LLM получает:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate_limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate limit exceeded for endpoint </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">abc123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: try again in 8 seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Wait for the cooldown period to expire, then try invoking the endpoint again. Use the search tool to find other endpoints you can call in the meantime.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>LLM может использовать эту информацию, чтобы подождать и повторить попытку или переключиться на другой эндпоинт.</p><h3 id="зачем-это-нужно" tabindex="-1">Зачем это нужно <a class="header-anchor" href="#зачем-это-нужно" aria-label="Permalink to &quot;Зачем это нужно&quot;">​</a></h3><ul><li><strong>Предотвращает случайные дублирующие вызовы</strong> — LLM может вызывать один и тот же эндпоинт несколько раз подряд</li><li><strong>Защищает от лимитов частоты API</strong> — многие API имеют собственные лимиты, и их превышение вызовет ошибки</li><li><strong>Экономит ресурсы</strong> — уменьшает ненужный сетевой трафик</li></ul><h2 id="конфигурация" tabindex="-1">Конфигурация <a class="header-anchor" href="#конфигурация" aria-label="Permalink to &quot;Конфигурация&quot;">​</a></h2><p>Вы можете отключить ограничитель частоты или изменить интервал охлаждения:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Полное отключение ограничителя частоты</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_ratelimiter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Пользовательский интервал охлаждения</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rate_limit_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">30s</span></span></code></pre></div><h3 id="disable-ratelimiter" tabindex="-1">disable_ratelimiter <a class="header-anchor" href="#disable-ratelimiter" aria-label="Permalink to &quot;disable_ratelimiter&quot;">​</a></h3><ul><li><strong>Тип:</strong> <code>bool</code></li><li><strong>По умолчанию:</strong> <code>false</code></li><li><strong>Эффект:</strong> При <code>true</code> ограничитель частоты на эндпоинт отключается. LLM может вызывать один и тот же эндпоинт повторно без ожидания.</li><li><strong>Когда включать:</strong> Тестирование, отладка или когда нужно вызывать один и тот же эндпоинт несколько раз подряд.</li><li><strong>Когда оставлять отключённым (рекомендуется):</strong> Продакшен. Ограничитель частоты предотвращает случайное злоупотребление.</li></ul><h3 id="rate-limit-interval" tabindex="-1">rate_limit_interval <a class="header-anchor" href="#rate-limit-interval" aria-label="Permalink to &quot;rate_limit_interval&quot;">​</a></h3><ul><li><strong>Тип:</strong> duration (Go-формат: <code>10s</code>, <code>30s</code>, <code>1m</code>)</li><li><strong>По умолчанию:</strong> <code>10s</code></li><li><strong>Эффект:</strong> Устанавливает период охлаждения между вызовами одного и того же эндпоинта.</li><li><strong>Когда увеличивать:</strong> API со строгими лимитами частоты (например, 10 запросов в минуту).</li><li><strong>Когда уменьшать:</strong> Внутренние API, где вы контролируете нагрузку.</li><li><strong>Примеры:</strong> <code>5s</code>, <code>30s</code>, <code>1m</code>, <code>2m</code></li></ul><h2 id="важные-замечания" tabindex="-1">Важные замечания <a class="header-anchor" href="#важные-замечания" aria-label="Permalink to &quot;Важные замечания&quot;">​</a></h2><ul><li><strong>Отслеживание на эндпоинт</strong> — каждый эндпоинт отслеживается независимо. Вызов одного эндпоинта не влияет на другие.</li><li><strong>Ошибка возвращается LLM</strong> — второй вызов в течение периода охлаждения отклоняется с ошибкой <code>rate_limit</code>. LLM получает длительность охлаждения и может повторить попытку после ожидания.</li><li><strong>Очистка не требуется</strong> — ограничитель частоты отслеживает эндпоинты автоматически и не требует обслуживания.</li></ul>`,23)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
